import sailpoint.object.Identity;
if (value == null) return null;
Identity id = (value instanceof Identity) ? (Identity) value
            : context.getObject(Identity.class, value.toString());
if (id == null) return "Identity not found.";
if (id.isWorkgroup()) return "Select a person, not a workgroup.";
if (id.getName().equals(context.getUserName())) return "You cannot disable or enable your own identity.";
return null;

