import sailpoint.object.Identity;
Object v = form.getField("targetIdentity").getValue();
if (v == null) return null;
Identity id = (v instanceof Identity) ? (Identity) v : context.getObject(Identity.class, v.toString());
if (id == null) return null;
return id.getDisplayableName() + " (" + id.getName() + ")";

