ValidationScript.Source:
import sailpoint.object.Identity;
if (value == null) return null;
Object v = form.getField("targetIdentity").getValue();
if (v == null) return null;
Identity id = (v instanceof Identity) ? (Identity) v : context.getObject(Identity.class, v.toString());
if (id == null) return null;
Object ed = id.getAttribute("emergencyDisable");
boolean on = (ed != null) && "true".equalsIgnoreCase(ed.toString().trim());
if (on && !"Enable".equals(value)) return "This identity is already disabled; it can only be enabled.";
if (!on && !"Disable".equals(value)) return "This identity is active; it can only be disabled.";
return null;

Script.Source:
import java.util.List;
import sailpoint.object.Capability;
import sailpoint.object.Identity;

String error = null;

// The quick link is only shown to administrators; check again in case the workflow is launched another way
Identity me = (launcher == null) ? null : context.getObjectByName(Identity.class, launcher);
boolean admin = false;
if (me != null) {
    List caps = me.getCapabilityManager().getEffectiveCapabilities();
    if (caps != null) {
        for (Object c : caps) {
            String n = ((Capability) c).getName();
            if ("SystemAdministrator".equals(n) || "EmergencyIdentityAdministrator".equals(n)) admin = true;
        }
    }
}

Identity target = null;
if (targetIdentity != null) {
    target = (targetIdentity instanceof Identity) ? (Identity) targetIdentity
           : context.getObject(Identity.class, targetIdentity.toString());
}
if (target != null) {
    workflow.put("identityName", target.getName());
    workflow.put("identityDisplayName", target.getDisplayableName());
} else if (targetIdentity != null) {
    workflow.put("identityName", targetIdentity.toString());
}

if (!admin) {
    error = "Requestor " + launcher + " is not an administrator.";
} else if (target == null) {
    error = "Identity " + targetIdentity + " not found.";
} else if (target.getName().equals(launcher)) {
    error = "Requestors cannot disable or enable their own identity.";
} else if (justification == null || justification.trim().length() == 0) {
    error = "A justification is required.";
} else {
    Object ed = target.getAttribute("emergencyDisable");
    boolean on = (ed != null) && "true".equalsIgnoreCase(ed.toString().trim());
    workflow.put("previousValue", Boolean.valueOf(on));
    if ("Disable".equals(requestedAction) && on) {
        error = target.getName() + " is already disabled.";
    } else if ("Enable".equals(requestedAction) && !on) {
        error = target.getName() + " is already active.";
    } else if (!"Disable".equals(requestedAction) && !"Enable".equals(requestedAction)) {
        error = "Unknown action " + requestedAction + ".";
    }
}

if (error != null) {
    workflow.put("validationError", error);
    workflow.put("workflowResult", "DENIED");
    List details = new java.util.ArrayList();
    details.add(error);
    workflow.put("resultDetails", details);
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import sailpoint.api.ObjectUtil;
import sailpoint.object.Identity;
import sailpoint.object.Rule;

boolean disable = "Disable".equals(requestedAction);
Identity id = null;
try {
    id = ObjectUtil.lockIdentity(context, identityName);
    if (id == null) throw new Exception("identity " + identityName + " not found");

    id.setAttribute("emergencyDisable", Boolean.valueOf(disable));

    // Lifecycle status: Disabled now, or back to the HR value on Enable
    Rule statusRule = context.getObjectByName(Rule.class, "HR Lifecycle - Status Attribute");
    if (statusRule != null) {
        Map sargs = new HashMap();
        sargs.put("identity", id);
        sargs.put("oldValue", id.getAttribute("status"));
        Object st = context.runRule(statusRule, sargs);
        if (st != null) id.setAttribute("status", st.toString());
    }

    // LCM disabled status: same calculation as the identity refresh
    Rule inactiveRule = context.getObjectByName(Rule.class, "Emergency Identity - Inactive Attribute");
    boolean inactive = disable;
    if (inactiveRule != null) {
        Map args = new HashMap();
        args.put("identity", id);
        args.put("oldValue", Boolean.valueOf(id.isInactive()));
        Object r = context.runRule(inactiveRule, args);
        inactive = (r != null) && "true".equalsIgnoreCase(r.toString());
    }
    id.setInactive(inactive);
    context.saveObject(id);
    workflow.put("newValue", Boolean.valueOf(disable));
} catch (Exception e) {
    log.error("Emergency Identity: could not update " + identityName, e);
    workflow.put("workflowResult", "FAILED");
    List details = new ArrayList();
    details.add("Identity not updated: " + e.getMessage());
    workflow.put("resultDetails", details);
} finally {
    // Saves and commits the identity
    if (id != null) ObjectUtil.unlockIdentity(context, id);
}

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

Map r = (Map) provisioningResult;
List details = new ArrayList();
details.add("Emergency Disable set to " + newValue + " on " + identityName + ".");
sailpoint.object.Identity updated = context.getObjectByName(sailpoint.object.Identity.class, identityName);
if (updated != null) {
    details.add("Lifecycle status: " + updated.getAttribute("status") + ", inactive: " + updated.isInactive() + ".");
}
if (r == null) {
    workflow.put("workflowResult", "FAILED");
    details.add("No result from the provisioning rule.");
} else {
    workflow.put("workflowResult", r.get("status"));
    if (r.get("details") != null) details.addAll((List) r.get("details"));
}
workflow.put("resultDetails", details);

StringBuilder sb = new StringBuilder();
if (resultDetails != null) {
    for (Object d : resultDetails) sb.append(d).append("\n");
}
workflow.put("resultText", sb.toString().trim());
